from scipy.optimize import least_squares
T=np.asarray(df['T'],float); e=np.asarray(df.eps,float); s=np.asarray(df.sigma,float)
print(np.ptp(T), np.ptp(e), np.ptp(s), s.min(), s.max())
def base(p):
    return p[0]+p[1]*np.abs(T)**p[3]+p[2]*T**2+p[5]*T+p[7]*T**3+p[4]*np.abs(e)**p[6]
best=None
for trial in range(30):
    p0=np.r_[np.random.randn(3),np.random.rand()*2+0.5,np.random.randn(),np.random.randn(),np.random.rand()*2+0.5, np.random.randn()]
    try:
        r=least_squares(lambda p: base(p)-s, p0, method='trf', max_nfev=5000)
        v=np.mean(r.fun**2)/np.var(s)
        if np.isfinite(v) and (best is None or v<best[0]): best=(v,r.x)
    except Exception as ex: pass
print(best)
res=s-base(best[1])
print(np.corrcoef(res,e)[0,1], np.corrcoef(res,T)[0,1])
for lo,hi in [(0,1),(1,2),(2,3),(3,4),(4,5.1)]:
    m=(e>=lo)&(e<hi); print('eps',lo,hi, m.sum(), np.round(res[m].mean(),6), np.round(res[m].std(),6))
for lo,hi in [(0,2.5),(2.5,3.5),(3.5,4.5),(4.5,7)]:
    m=(T>=lo)&(T<hi); print('T',lo,hi, m.sum(), np.round(res[m].mean(),6) if m.sum() else None)
